<script lang="ts">import Icon from '$lib/components/Icon.svelte';import {command} from '$lib/database/store';import type {Database} from '$lib/database/model';export let database:Database;let importOpen=false,file:File|null=null,ack=false,error='',notice='';function record(label:string){command({type:'operation',database:database.id,label});notice=label;error='';}function simulateImport(){if(!file||!ack)return; if(!/\.(sql|gz|zip)$/i.test(file.name)){error='Choose an SQL, GZ or ZIP backup.';return;}record('Selected '+file.name+' for sample import; no SQL executed.');file=null;ack=false;importOpen=false;}async function exportFile(gzip:boolean){try{const sql='-- Drevanta demo export: '+database.name+'\n-- No real schema or database data.\n'+database.tables.map(t=>'-- Example table: '+t).join('\n')+'\n';let blob=new Blob([sql],{type:'text/plain'});if(gzip){if(typeof CompressionStream==='undefined')throw Error('Gzip export is not supported by this browser.');blob=await new Response(blob.stream().pipeThrough(new CompressionStream('gzip'))).blob();}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=database.name+'.sql'+(gzip?'.gz':'');document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);record(gzip?'GZ sample exported':'SQL sample exported');}catch(e){error=e instanceof Error?e.message:'Export failed.';}}</script>
<section class="card stack"><div><h3>Database Operations</h3><p class="subtitle">Upload a backup, export sample SQL or preview database maintenance.</p></div><div class="db6-operation-grid"><button class="btn secondary" on:click={()=>importOpen=!importOpen}><Icon name="Upload"/>Import</button><button class="btn secondary" on:click={()=>exportFile(false)}><Icon name="Storage"/>Export as SQL</button><button class="btn secondary" on:click={()=>exportFile(true)}><Icon name="Storage"/>Export as GZ</button>{#each ['Check','Repair','Optimize'] as op}<button class="btn secondary" disabled={op==='Repair'&&database.engine==='PostgreSQL'} on:click={()=>record(op+' requested (simulation)')}><Icon name={op==='Check'?'Search':op==='Repair'?'Settings':'Monitoring'}/>{op}</button>{/each}</div>{#if importOpen}<form class="stack well" on:submit|preventDefault={simulateImport}><label class="field">Choose SQL backup<input type="file" accept=".sql,.gz,.zip" required on:change={(e)=>file=e.currentTarget.files?.[0]||null}/></label><label class="check"><input type="checkbox" bind:checked={ack} required/> I understand a real import may overwrite tables.</label><div><button class="btn primary" type="submit" disabled={!file||!ack}>Simulate import</button></div></form>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}<small>{database.engine==='PostgreSQL'?'Repair is not supported for PostgreSQL.':'Repair is limited to supported MySQL/MariaDB table engines.'} No live database operations are performed.</small></section>
